UPDATE trivia.questions q
   SET options_scale = p.scale,
       updated_at    = now()
  FROM proposed p
 WHERE q.id = p.id
   AND q.options_scale IS NULL
   AND q.status = 'active'
   AND q.options->>q.correct_answer = p.scale->>3;

-- Post-verify gate. Reads the END STATE, so a partial apply or a re-run is judged on
-- what is actually in the table, never on a rowcount.
DO $$
DECLARE
  v_scaled     int;
  v_misplaced  int;
  v_wrong_len  int;
  v_wrong_side int;
BEGIN
  SELECT count(*) INTO v_scaled FROM trivia.questions WHERE options_scale IS NOT NULL;

  SELECT count(*) INTO v_misplaced
    FROM trivia.questions
   WHERE options_scale IS NOT NULL
     AND options_scale->>3 IS DISTINCT FROM options->>correct_answer;

  SELECT count(*) INTO v_wrong_len
    FROM trivia.questions
   WHERE options_scale IS NOT NULL AND jsonb_array_length(options_scale) <> 7;

  -- The rule this migration exists for, asserted against the data rather than trusted
  -- from the generator: no year-dated scale may straddle today.
  SELECT count(*) INTO v_wrong_side
    FROM trivia.questions q
   CROSS JOIN LATERAL (
     SELECT min((m)::int) AS lo, max((m)::int) AS hi
       FROM jsonb_array_elements_text(q.options_scale) AS m
      WHERE m ~ '^[0-9]{4}$'
   ) s
   WHERE q.options_scale IS NOT NULL
     AND s.lo IS NOT NULL
     AND s.lo >= 1500 AND s.hi <= 2100
     AND q.options_scale->>3 ~ '^[0-9]{4}$'
     AND (
       ((q.options_scale->>3)::int <= extract(year FROM now())::int AND s.hi > extract(year FROM now())::int)
       OR
       ((q.options_scale->>3)::int >  extract(year FROM now())::int AND s.lo < extract(year FROM now())::int)
     );

  IF v_misplaced > 0 THEN
    RAISE EXCEPTION 'CC_0287: % scale(s) whose mark 4 is not the stored answer', v_misplaced;
  END IF;
  IF v_wrong_len > 0 THEN
    RAISE EXCEPTION 'CC_0287: % scale(s) that are not 7 marks long', v_wrong_len;
  END IF;
  IF v_wrong_side > 0 THEN
    RAISE EXCEPTION 'CC_0287: % year scale(s) straddle today -- a mark on the wrong side of now', v_wrong_side;
  END IF;
  IF v_scaled < 524 THEN
    RAISE EXCEPTION 'CC_0287: expected at least % scaled questions, found %', 524, v_scaled;
  END IF;

  RAISE NOTICE 'CC_0287: % questions carry a 7-mark scale; no year scale straddles today', v_scaled;
END $$;

COMMIT;
